	/**
	 * Default Constructor
	 */
    public PaymentCardService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new PaymentCardEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(PaymentCardRepository.class) );
		this.validator		= applicationContext.getBean(PaymentCardValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		PaymentCard
	 */
		public PaymentCard createPaymentCard( CreatePaymentCardCommand command ) {

		PaymentCard entity = new PaymentCard();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPaymentCardId( command.getPaymentCardId() );
            entity.setCardNumber( command.getCardNumber() );
            entity.setEmbossedName( command.getEmbossedName() );
            entity.setExpiryMonth( command.getExpiryMonth() );
            entity.setExpiryYear( command.getExpiryYear() );
            entity.setCardType( command.getCardType() );
            entity.setCardStatus( command.getCardStatus() );
            entity.setNetwork( command.getNetwork() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of PaymentCard {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdatePaymentCardCommand
	 * @return		PaymentCard
	 */
	public PaymentCard updatePaymentCard( UpdatePaymentCardCommand command ) {

		PaymentCard entity = new PaymentCard();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setPaymentCardId( command.getPaymentCardId() );
            entity.setCardNumber( command.getCardNumber() );
            entity.setEmbossedName( command.getEmbossedName() );
            entity.setExpiryMonth( command.getExpiryMonth() );
            entity.setExpiryYear( command.getExpiryYear() );
            entity.setBank( command.getBank() );
            entity.setAccount( command.getAccount() );
            entity.setCustomer( command.getCustomer() );
            entity.setTransactions( command.getTransactions() );
            entity.setCardType( command.getCardType() );
            entity.setCardStatus( command.getCardStatus() );
            entity.setNetwork( command.getNetwork() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of PaymentCard {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeletePaymentCardCommand
	 */
	public void delete( DeletePaymentCardCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getPaymentCardId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of PaymentCard {0} ", id );

	}

	/**
	 * Method to retrieve the PaymentCard via PaymentCardFetchOneSummary
	 * @param 	summary PaymentCardFetchOneSummary
	 * @return 	PaymentCardFetchOneResponse
	 */
	public PaymentCard getPaymentCard( PaymentCardFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "PaymentCardFetchOneSummary arg cannot be null" );

		PaymentCard entity = null;
		UUID id = summary.getPaymentCardId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a PaymentCard using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all PaymentCards
	 *
	 * @return 	List<PaymentCard>
	 */
    public List<PaymentCard> getAllPaymentCard() {
		List<PaymentCard> list = projector.findAll( new FindAllPaymentCardQuery() );
		return list;
	}

	/**
	 * assign Bank on PaymentCard
	 * @param		command AssignBankToPaymentCardCommand
	 */
	public void assignBank( AssignBankToPaymentCardCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignBank(command.getPaymentCardId(), command.getAssignment());

	}

